"use client";

import { forwardRef, useRef, type HTMLAttributes, type ReactNode } from "react";
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { DigitColumn, springFromDuration } from "./DigitColumn";
import { sanitize, toParts } from "./format";

// An integer that rolls like an odometer whenever `value` changes. Every place is its own
// spring-driven wheel (see DigitColumn), started right to left with a small stagger so the change
// ripples across the number. When the number gains or loses places, the new digit and its
// separator grow in from zero width and the rest of the number slides over to make room.

export interface NumberTickerProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children" | "prefix"> {
  /** The number to show. Rounded to an integer; non-finite values keep the last good one. */
  value: number;
  /** Locale for digit grouping, e.g. `de-DE` gives 1.234. */
  locale?: string;
  /** Static text before the number, e.g. `$`. */
  prefix?: string;
  /** Static text after the number, e.g. `%`. */
  suffix?: string;
  /** Seconds a one-place step takes to settle; bigger jumps stretch from this. */
  duration?: number;
  /** Overshoot on a one-place step, 0–1; bigger jumps overshoot less. 0 glides in with none. */
  bounce?: number;
  /** Raw spring for the roll; overrides `duration` and `bounce`. */
  spring?: { stiffness?: number; damping?: number; mass?: number };
  /** Seconds between places starting to roll, from the units leftward. */
  stagger?: number;
  /** Maximum vertical motion blur, in px. 0 turns it off. */
  blur?: number;
  /** Briefly tint changed digits: `upColor` when the value rises, `downColor` when it falls. */
  flash?: boolean;
  upColor?: string;
  downColor?: string;
  /** Roll up from 0 on first render. */
  animateOnMount?: boolean;
}

export const NumberTicker = forwardRef<HTMLSpanElement, NumberTickerProps>(function NumberTicker(
  {
    value,
    locale = "en-US",
    prefix,
    suffix,
    duration = 0.45,
    bounce = 0.25,
    spring,
    stagger = 0.04,
    blur = 8,
    flash = false,
    upColor = "#4ade80",
    downColor = "#f87171",
    animateOnMount = true,
    className,
    style,
    ...rest
  },
  ref,
) {
  const reduced = useReducedMotion() ?? false;
  const springConfig = { ...springFromDuration(duration, bounce), ...spring };

  const lastFinite = useRef(0);
  const v = sanitize(value, lastFinite.current);
  lastFinite.current = v;

  // Direction of the most recent change. Refs keep it stable across StrictMode's double render.
  const prev = useRef(v);
  const direction = useRef<-1 | 0 | 1>(0);
  if (v !== prev.current) {
    direction.current = v > prev.current ? 1 : -1;
    prev.current = v;
  }

  // The sign leads the prefix, so negatives read -$1,234 rather than $-1,234.
  const all = toParts(v, locale);
  const sign = all.filter((p) => p.kind === "sign");
  const parts = all.filter((p) => p.kind !== "sign");
  const magnitude = Math.abs(v);
  const text = (ps: typeof all) => ps.map((p) => (p.kind === "digit" ? p.digit : p.char)).join("");
  const label = `${text(sign)}${prefix ?? ""}${text(parts)}${suffix ?? ""}`;

  // Places that mount after the first render grow in; on first render only if animating in.
  const enter = { width: 0, opacity: 0, filter: "blur(6px)", overflowX: "clip" as const };
  const settled = {
    width: "auto",
    opacity: 1,
    filter: "blur(0px)",
    transitionEnd: { overflowX: "visible" as const, filter: "none" },
  };
  const morph = reduced ? { duration: 0 } : { type: "spring" as const, ...springConfig };
  // Not gated on `reduced`: the server can't know it, so markup must not depend on it. Reduced
  // motion instead zeroes the transitions and makes the columns jump.
  const playIn = animateOnMount;

  const morphing = (key: string, child: ReactNode) => (
    <motion.span
      key={key}
      layout="position"
      className="inline-block"
      initial={enter}
      animate={settled}
      exit={{ ...enter, transition: morph }}
      transition={morph}
    >
      {child}
    </motion.span>
  );

  return (
    <span
      ref={ref}
      className={cn("relative inline-flex items-baseline whitespace-nowrap tabular-nums", className)}
      style={style}
      {...rest}
    >
      <span className="sr-only" aria-live="polite">
        {label}
      </span>
      <LayoutGroup>
        <span aria-hidden className="inline-flex items-baseline">
          <AnimatePresence initial={playIn}>
            {sign.map((part) => morphing(part.key, part.kind === "sign" && part.char))}
          </AnimatePresence>
          {prefix && <motion.span layout="position">{prefix}</motion.span>}
          <AnimatePresence initial={playIn}>
            {parts.map((part) => {
              if (part.kind !== "digit") return morphing(part.key, part.char);
              const target = Math.floor(magnitude / 10 ** part.place);
              return morphing(
                part.key,
                <DigitColumn
                  target={target}
                  direction={direction.current}
                  delay={reduced ? 0 : part.place * stagger}
                  duration={duration}
                  bounce={bounce}
                  spring={spring && springConfig}
                  blur={blur}
                  flash={flash}
                  upColor={upColor}
                  downColor={downColor}
                  reduced={reduced}
                  initial={playIn ? 0 : target}
                />,
              );
            })}
          </AnimatePresence>
          {suffix && <motion.span layout="position">{suffix}</motion.span>}
        </span>
      </LayoutGroup>
    </span>
  );
});

"use client";

import { useEffect, useId, useRef } from "react";
import {
  animate,
  motion,
  useMotionTemplate,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  useVelocity,
  type AnimationPlaybackControls,
  type MotionValue,
} from "framer-motion";

// One digit place of the ticker, drawn as an odometer wheel. The column springs a continuous
// position (the whole value at this place and above, e.g. 123 for the tens of 1,234) and draws the
// ten digits around `position mod 10`, so a rising value always rolls up and a falling one always
// rolls down, straight through 9 → 0. A column only ever turns as far as its digit changes (at most
// nine faces), and longer turns get a little more time and almost no bounce, so big jumps glide in
// rather than whipping round and overshooting. The spring's velocity drives a vertical-only SVG
// blur, which reads as motion blur rather than the soft focus a CSS `blur()` gives.

export interface DigitColumnProps {
  /** floor(|value| / 10^place) — the column's continuous target. */
  target: number;
  /** Direction of the last value change, for the flash color. */
  direction: -1 | 0 | 1;
  /** Seconds before this column starts moving (place × stagger). */
  delay: number;
  /** Seconds a one-face turn takes to settle; longer turns stretch from this. */
  duration: number;
  /** Overshoot on a one-face turn, 0–1; longer turns overshoot less. */
  bounce: number;
  /** Raw spring for every turn, overriding the distance-aware `duration` and `bounce`. */
  spring?: { stiffness: number; damping: number; mass: number };
  /** Maximum motion blur, in px. */
  blur: number;
  flash: boolean;
  upColor: string;
  downColor: string;
  /** Swap digits instantly, with no roll, blur or flash. */
  reduced: boolean;
  /** Position on mount: 0 to roll in, `target` to start settled. */
  initial: number;
  /** Faces on the wheel. 10 for an odometer; a clock's tens of seconds uses 6. */
  base?: number;
}

/**
 * A spring that takes about `duration` seconds to settle, overshooting by `bounce` (0–1), with the
 * same mapping framer-motion uses for its own `visualDuration`.
 */
export function springFromDuration(duration: number, bounce: number) {
  const root = (2 * Math.PI) / (Math.max(0.05, duration) * 1.2);
  const stiffness = root * root;
  const damping = 2 * Math.min(1, Math.max(0.05, 1 - bounce)) * Math.sqrt(stiffness);
  return { stiffness, damping, mass: 1 };
}

// Velocity (cells/s) → blur (px).
const BLUR_PER_SPEED = 0.35;
// The window extends this far above and below the glyph, so the edge fade never touches a
// settled digit.
const PAD = "0.15em";
// Side room so the flash glow isn't cut off by the mask; cancelled by a negative margin.
const GLOW_ROOM = "0.3em";
const MASK =`linear-gradient(to bottom, transparent 0, #000 ${PAD}, #000 calc(100% - ${PAD}), transparent 100%)`;

/** Offset of digit `i` from the window, in cells, wrapped to [-base/2, base/2). */
function cellOffset(i: number, position: number, base: number) {
  const m = (((i - position) % base) + base) % base;
  return m >= base / 2 ? m - base : m;
}

function Cell({ digit, position, base }: { digit: number; position: MotionValue<number>; base: number }) {
  const y = useTransform(position, (p) => `${cellOffset(digit, p, base) * 100}%`);
  // Neighbours fade out with distance, so nothing peeks into the window's padding at rest.
  const opacity = useTransform(position, (p) => Math.max(0, 1 - Math.abs(cellOffset(digit, p, base))));
  return (
    <motion.span className="absolute inset-x-0 text-center" style={{ top: PAD, bottom: PAD, y, opacity }}>
      {digit}
    </motion.span>
  );
}

export function DigitColumn({
  target,
  direction,
  delay,
  duration,
  bounce,
  spring,
  blur,
  flash,
  upColor,
  downColor,
  reduced,
  initial,
  base = 10,
}: DigitColumnProps) {
  const filterId = `nt-blur-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const position = useMotionValue(initial);
  const velocity = useVelocity(position);
  const stripRef = useRef<HTMLSpanElement>(null);
  const blurRef = useRef<SVGFEGaussianBlurElement>(null);

  // Flash: `glow` runs 0–1 and mixes the up/down color into the inherited text color.
  const glow = useMotionValue(0);
  const flashColor = useMotionValue(upColor);
  const glowPct = useTransform(glow, (g) => g * 100);
  const glowRadius = useTransform(glow, (g) => g * 14);
  const color = useMotionTemplate`color-mix(in oklab, ${flashColor} ${glowPct}%, currentColor)`;
  const textShadow = useMotionTemplate`0 0 ${glowRadius}px color-mix(in oklab, ${flashColor} ${glowPct}%, transparent)`;

  const mounted = useRef(false);
  const glowControls = useRef<AnimationPlaybackControls | null>(null);
  const flashToken = useRef(0);

  useEffect(() => {
    const first = !mounted.current;
    mounted.current = true;

    if (reduced) {
      position.jump(target);
      return;
    }

    // Turn only as far as the digit changes: drop whole turns by jumping a multiple of `base`,
    // which draws the same face, so there's no visible snap.
    const gap = target - position.get();
    const travel = Math.abs(gap) % base;
    const velocity = position.getVelocity();
    if (Math.abs(gap) >= base) position.jump(target - Math.sign(gap) * travel);
    // A spring's overshoot scales with distance, so spread the bounce over the turn and give long
    // turns a bit more time: a nine-face roll takes ~1.6× a single step and barely overshoots.
    const timing =
      spring ??
      springFromDuration(duration * (1 + 0.2 * Math.sqrt(Math.max(0, travel - 1))), bounce / Math.sqrt(Math.max(1, travel)));
    // Carry the live velocity, so a change mid-roll retargets smoothly instead of restarting.
    const roll = animate(position, target, { type: "spring", ...timing, velocity, delay });

    if (!first && flash && direction !== 0) {
      flashColor.set(direction > 0 ? upColor : downColor);
      // Only the latest flash may fade out; a superseded one resolving late must not cut it short.
      const token = ++flashToken.current;
      glowControls.current?.stop();
      glowControls.current = animate(glow, 1, { duration: 0.12, delay });
      glowControls.current.then(() => {
        if (token !== flashToken.current) return;
        glowControls.current = animate(glow, 0, { duration: 0.6, delay: 0.25 });
      });
    }

    return () => roll.stop();
    // Only a new target starts a roll; prop tweaks apply to the next one.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, reduced]);

  useEffect(() => () => glowControls.current?.stop(), []);

  useMotionValueEvent(velocity, "change", (v) => {
    const y = Math.min(blur, Math.abs(v) * BLUR_PER_SPEED);
    blurRef.current?.setAttribute("stdDeviation", `0 ${y}`);
    // Drop the filter when settled so idle digits stay pixel-crisp.
    if (stripRef.current) stripRef.current.style.filter = y > 0.05 ? `url(#${filterId})` : "";
  });

  return (
    <span
      aria-hidden
      className="relative inline-block overflow-clip"
      style={{
        padding: `${PAD} ${GLOW_ROOM}`,
        margin: `-${PAD} -${GLOW_ROOM}`,
        maskImage: MASK,
        WebkitMaskImage: MASK,
      }}
    >
      <svg width="0" height="0" className="absolute" aria-hidden focusable="false">
        <filter id={filterId} x="-20%" y="-50%" width="140%" height="200%">
          <feGaussianBlur ref={blurRef} stdDeviation="0 0" />
        </filter>
      </svg>
      {/* Sizes the window: tabular digits all share this width. */}
      <span className="invisible">0</span>
      <motion.span
        ref={stripRef}
        className="absolute inset-0"
        style={{ color, textShadow }}
      >
        {Array.from({ length: base }, (_, d) => (
          <Cell key={d} digit={d} position={position} base={base} />
        ))}
      </motion.span>
    </span>
  );
}

// Splits a number into the pieces the ticker renders. Digits are keyed by their place counted from
// the right (units are `d0`), never by their index, so when 999 becomes 1,000 the existing places
// keep their identity and only the new thousands digit and its separator mount.

export type TickerPart =
  | { kind: "digit"; key: string; digit: number; place: number }
  | { kind: "group"; key: string; char: string }
  | { kind: "sign"; key: "sign"; char: string };

/** Rounds finite values to an integer; anything else falls back (to the last good value). */
export function sanitize(value: number, fallback: number): number {
  return Number.isFinite(value) ? Math.round(value) : fallback;
}

const formatters = new Map<string, Intl.NumberFormat>();

function formatter(locale: string) {
  let f = formatters.get(locale);
  if (!f) {
    f = new Intl.NumberFormat(locale, { maximumFractionDigits: 0, useGrouping: true });
    formatters.set(locale, f);
  }
  return f;
}

export function toParts(value: number, locale = "en-US"): TickerPart[] {
  const raw = formatter(locale).formatToParts(sanitize(value, 0));
  const out: TickerPart[] = [];
  let place = 0;
  // Walk right to left so every digit knows its place value.
  for (let i = raw.length - 1; i >= 0; i--) {
    const { type, value: text } = raw[i];
    if (type === "integer") {
      for (let j = text.length - 1; j >= 0; j--) {
        out.push({ kind: "digit", key: `d${place}`, digit: Number(text[j]), place });
        place++;
      }
    } else if (type === "group") {
      // Named after the digit to its right: the comma in 1,234 is `g2`.
      out.push({ kind: "group", key: `g${place - 1}`, char: text });
    } else if (type === "minusSign") {
      out.push({ kind: "sign", key: "sign", char: text });
    }
  }
  return out.reverse();
}

"use client";

import { useEffect, useState, type HTMLAttributes } from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { DigitColumn } from "./DigitColumn";

// A live HH:MM:SS clock on the ticker's odometer wheels, set into a recessed well. Each digit is
// its own wheel with as many faces as that digit can show (the tens of minutes has six), and it
// only ever turns forward, so 59 → 00 steps up to the next face instead of spinning back.

export interface NumberTickerClockProps extends HTMLAttributes<HTMLDivElement> {
  /** Show the seconds wheels. */
  showSeconds?: boolean;
  /** Seconds a roll takes to settle. */
  duration?: number;
  /** Overshoot before settling, 0–1. */
  bounce?: number;
  /** Seconds between neighbouring wheels starting to roll, from the right. */
  stagger?: number;
  /** Maximum vertical motion blur, in px. */
  blur?: number;
}

// Faces per wheel: H H : M M : S S.
const BASES = [3, 10, 6, 10, 6, 10];
const ZERO = [0, 0, 0, 0, 0, 0];

function digitsOf(d: Date) {
  const [h, m, s] = [d.getHours(), d.getMinutes(), d.getSeconds()];
  return [Math.floor(h / 10), h % 10, Math.floor(m / 10), m % 10, Math.floor(s / 10), s % 10];
}

type Wheels = { digits: number[]; turns: number[] };

/** Advance every wheel forward to its new digit; `turns` is the wheel's running position. */
function advance(prev: Wheels, digits: number[]): Wheels {
  const turns = prev.turns.map((t, i) => t + ((digits[i] - prev.digits[i] + BASES[i]) % BASES[i]));
  return { digits, turns };
}

function Colon() {
  return (
    <span aria-hidden className="mx-[0.14em] flex h-[0.56em] flex-col justify-between self-center">
      <span className="size-[0.1em] rounded-full bg-neutral-500 shadow-[0_1px_0_rgba(0,0,0,0.8)]" />
      <span className="size-[0.1em] rounded-full bg-neutral-500 shadow-[0_1px_0_rgba(0,0,0,0.8)]" />
    </span>
  );
}

export function NumberTickerClock({
  showSeconds = true,
  duration = 0.45,
  bounce = 0.25,
  stagger = 0.04,
  blur = 8,
  className,
  ...rest
}: NumberTickerClockProps) {
  const reduced = useReducedMotion() ?? false;
  // Starts at 00:00:00 so server and client markup match; the first tick rolls up to the time.
  const [wheels, setWheels] = useState<Wheels>({ digits: ZERO, turns: ZERO });

  useEffect(() => {
    let id: ReturnType<typeof setTimeout>;
    const tick = () => {
      const now = new Date();
      setWheels((w) => advance(w, digitsOf(now)));
      // Land just after each second boundary so the wheels turn on the second.
      id = setTimeout(tick, 1000 - now.getMilliseconds() + 5);
    };
    tick();
    return () => clearTimeout(id);
  }, []);

  const count = showSeconds ? 6 : 4;
  const [h1, h2, m1, m2, s1, s2] = wheels.digits;
  const label = `${h1}${h2}:${m1}${m2}${showSeconds ? `:${s1}${s2}` : ""}`;

  const wheel = (i: number) => (
    <DigitColumn
      key={i}
      target={wheels.turns[i]}
      direction={1}
      delay={reduced ? 0 : (count - 1 - i) * stagger}
      duration={duration}
      bounce={bounce}
      blur={blur}
      flash={false}
      upColor=""
      downColor=""
      reduced={reduced}
      initial={0}
      base={BASES[i]}
    />
  );

  return (
    <div
      role="timer"
      aria-label={label}
      className={cn(
        "inline-flex items-center rounded-2xl border border-white/[0.03] border-t-black/80 border-b-white/10 bg-[#060708] px-[0.4em] py-[0.18em] text-6xl font-semibold tracking-tight text-neutral-100 tabular-nums shadow-[inset_0_2px_5px_rgba(0,0,0,0.9),inset_0_-1px_0_rgba(255,255,255,0.03)] select-none",
        className,
      )}
      {...rest}
    >
      {wheel(0)}
      {wheel(1)}
      <Colon />
      {wheel(2)}
      {wheel(3)}
      {showSeconds && (
        <>
          <Colon />
          {wheel(4)}
          {wheel(5)}
        </>
      )}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
